parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "bug_crash",
        "login_account",
        "billing_subscription",
        "performance",
        "ads",
        "feature_request",
        "praise",
        "spam_irrelevant",
        "other"
      ],
      "description": "Main topic of the review"
    },
    "severity": {
      "type": "string",
      "enum": [
        "urgent",
        "high",
        "medium",
        "low"
      ],
      "description": "urgent = many users likely blocked (crash on start, cannot log in, charged wrongly, data loss); high = a core feature broken; medium = annoying; low = praise, wishes, spam"
    },
    "summary": {
      "type": "string",
      "description": "One short English sentence describing the user's problem or point"
    },
    "language": {
      "type": "string",
      "description": "ISO code of the review language"
    },
    "replyDraft": {
      "type": "string",
      "description": "A polite reply from the developer, under 350 characters, in the review's language. Thank the user, address the issue, no promises of dates, no personal data requests. Empty for spam."
    }
  },
  "required": [
    "category",
    "severity",
    "summary",
    "language",
    "replyDraft"
  ]
}

parameters.jsCode:
// Join each AI result back to its review (same order) and flatten for Sheets and Slack.
const reviews = $('Filter New Reviews').all();
return $input.all().map((item, i) => {
  const r = reviews[i].json;
  const ai = item.json.output ?? {};
  return { json: {
    date: r.reviewedAt,
    app: r.appName,
    appId: r.appId,
    country: r.country,
    rating: r.rating,
    version: r.version ?? '',
    category: ai.category ?? 'other',
    severity: ai.severity ?? 'medium',
    summary: ai.summary ?? '',
    review: r.text,
    replyDraft: ai.replyDraft ?? '',
    language: ai.language ?? '',
    reviewUrl: r.reviewUrl ?? '',
    reviewId: r.reviewId,
  } };
});

// Everything that was not urgent, as one daily digest grouped by category.
const rows = $input.all().map(i => i.json);
const byCat = {};
for (const r of rows) (byCat[r.category] ??= []).push(r);
const order = Object.entries(byCat).sort((a, b) => b[1].length - a[1].length);
const lines = [`:bar_chart: *Daily review digest*: ${rows.length} new reviews (not urgent)`];
for (const [cat, list] of order) {
  const avg = (list.reduce((s, r) => s + r.rating, 0) / list.length).toFixed(1);
  lines.push(`\n*${cat.replace(/_/g, ' ')}* · ${list.length} · avg ${avg}★`);
  for (const r of list.slice(0, 3)) lines.push(`• ${r.app}: ${r.summary}`);
}
return [{ json: { text: lines.join('\n') } }];

// Rating and release warnings from the Actor's per-app summary rows. Runs even on days with no new reviews.
const summaries = $input.all().map(i => i.json).filter(r => r.type === 'app_summary');
const signed = v => (v === undefined || v === null) ? 'n/a' : (v > 0 ? '+' : '') + v;
const warn = summaries
  .filter(s => s.ratingTrend === 'declining' || (s.latestVersionVsPreviousRating ?? 0) <= -0.5)
  .map(s => `:warning: *${s.appName}*: 7-day rating ${s.last7DaysAvgRating} vs ${s.previous7DaysAvgRating} the week before; version ${s.latestVersion} is rated ${signed(s.latestVersionVsPreviousRating)} vs the previous version.`);
return warn.length ? [{ json: { text: warn.join('\n') } }] : [];
